// Generates the DESKTOP copy of web screens the PC app did not have, with everything they import, from the web app's TypeScript.
//
//   node scripts/port_web_screens.mjs                (from raptor-app/)  -> writes <PC app>/raptor-ui/src/webapp/
//   node scripts/port_web_screens.mjs <src folder>   another PC app source folder
//
// It strips the types and rewrites imports. A few web files are replaced by hand-written desktop ones (SHIMS, in webapp/shims/), and the
// shared call, competitor and import logic points at the copies the other generators make. Never edit the generated files by hand:
// change the web source and run this again.
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const ts = require('typescript');
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const WEB = path.join(ROOT, 'src');
const DESK = path.resolve(process.argv[2] || process.env.RAPTOR_DESKTOP_SRC || path.join(ROOT, '../../shoonya origins tech/Raptor B2B/raptor-ui/src'));
const OUT = path.join(DESK, 'webapp');
const HEADER = '// GENERATED by raptor-app/scripts/port_web_screens.mjs from the web app\'s TypeScript. Do not edit here: change the web source and run the script again.\n/* eslint-disable */\n';

export const SCREENS = [
  ...['Overview', 'Dashboard', 'Pipeline', 'Forecast', 'Inbox', 'Attention', 'Weekly', 'Quotes', 'Contacts', 'Companies', 'Tasks', 'Activity',
    'Automations', 'Forms', 'Booking', 'Campaigns', 'Tickets', 'Analytics', 'Reports', 'Marketing', 'Api', 'Trash', 'Guide'].map((n) => `pages/crm/Crm${n}.tsx`),
  'components/crm/WhatsAppDispatcher.tsx',                // sends the queued CRM WhatsApp messages while the app is open
  'pages/calls/CallsAsk.tsx', 'pages/calls/CallDetail.tsx',
  'hooks/useDirectory.ts', 'lib/team.ts',                 // also used by the desktop import wizard (port_import_desktop.mjs)
];
// web file -> the desktop file that stands in for it (relative to raptor-ui/src)
const SHIMS = {
  'lib/supabaseClient.ts': 'webapp/shims/supabaseClient.js',
  'lib/config.ts': 'webapp/shims/config.js',
  'hooks/AuthContext.tsx': 'webapp/shims/AuthContext.js',
  'hooks/OrgContext.tsx': 'webapp/shims/OrgContext.js',
  'components/crm/ReportView.tsx': 'webapp/shims/ReportView.js',
  'lib/desktop.tsx': 'webapp/shims/desktop.js',            // what only the PC app can do, inside the shared screens
  'lib/currency.ts': 'webapp/shims/currency.js',          // the account's currency, as the rest of the PC app shows it
};
// libraries the PC app does not carry -> the desktop file that stands in
const PACKAGES = { recharts: 'webapp/shims/recharts.js' };
// folders another generator already keeps a copy of
const ELSEWHERE = [['lib/calls/', 'pages/calls/shared/'], ['lib/competitors/', 'pages/competitors/shared/'], ['lib/import/', 'pages/crm/import/']];
// small differences of the desktop window
const REPLACE = {
  'components/crm/CloudSync.tsx': [['window.location.assign(out.url);', 'openExternal(out.url);', "import { openExternal } from '../../../openExternal';\n"]],
};

const posix = (p) => p.split(path.sep).join('/');
function resolveWeb(from, spec) {
  const base = path.join(path.dirname(path.join(WEB, from)), spec);
  for (const candidate of [base, `${base}.ts`, `${base}.tsx`, path.join(base, 'index.ts')]) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return posix(path.relative(WEB, candidate));
  }
  return null;
}
function desktopPath(web) {
  if (SHIMS[web]) return SHIMS[web];
  for (const [from, to] of ELSEWHERE) {
    if (web.startsWith(from)) {
      const target = to + web.slice(from.length).replace(/\.tsx?$/, '.js');
      return fs.existsSync(path.join(DESK, target)) ? target : null;      // not generated there: take our own copy
    }
  }
  return null;
}
const own = (web) => `webapp/${web.replace(/\.tsx?$/, '.js')}`;
const target = (web) => desktopPath(web) || own(web);

const todo = [...SCREENS];
const written = new Map();
while (todo.length) {
  const web = todo.pop();
  if (written.has(web) || desktopPath(web)) continue;
  if (web.endsWith('.css')) throw new Error(`a stylesheet is imported: ${web}`);
  let source = fs.readFileSync(path.join(WEB, web), 'utf8').replace(/\r\n/g, '\n');
  source = source.replace(/import\.meta\.env\.\w+\s*\|\|\s*/g, '');               // the desktop build has no Vite settings
  if (source.includes('import.meta')) throw new Error(`${web} uses import.meta: it needs a stand-in`);
  let extra = '';
  for (const [find, put, added] of REPLACE[web] || []) {
    if (!source.includes(find)) throw new Error(`${web}: the line to change is gone: ${find}`);
    source = source.replace(find, put);
    extra += added || '';
  }
  let js = ts.transpileModule(source, {
    fileName: web, compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2022, jsx: ts.JsxEmit.Preserve, removeComments: false },
  }).outputText;
  // only real statements (at the start of a line) and import(...), never an example in a comment
  js = js.replace(/(^(?:import|export)\b[^'";]*?|\bimport\()(['"])(\.{1,2}\/[^'"]+)\2/gm, (whole, lead, quote, spec) => {
    const found = resolveWeb(web, spec);
    if (!found) throw new Error(`${web}: cannot find ${spec}`);
    todo.push(found);
    let to = posix(path.relative(path.dirname(own(web)), target(found)));
    if (!to.startsWith('.')) to = `./${to}`;
    return `${lead}${quote}${to}${quote}`;
  });
  js = js.replace(/(^(?:import|export)\b[^'";]*?)(['"])([a-z@][^'"]*)\2/gm, (whole, lead, quote, name) => {
    if (!PACKAGES[name]) return whole;
    let to = posix(path.relative(path.dirname(own(web)), PACKAGES[name]));
    if (!to.startsWith('.')) to = `./${to}`;
    return `${lead}${quote}${to}${quote}`;
  });
  // the PC build's lint setup does not know this rule, and naming an unknown rule stops the build
  js = js.replace(/[ \t]*(?:\/\/|\{?\/\*)[ \t]*eslint-disable[\w-]*[ \t]+react-hooks\/exhaustive-deps[ \t]*(?:\*\/\}?)?/g, '');
  written.set(web, HEADER + extra + js);
}

// files that are no longer needed go, so an old copy is never left behind
const keep = new Set([...written.keys()].map((web) => path.join(DESK, own(web))));
const sweep = (dir) => {
  if (!fs.existsSync(dir)) return;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) sweep(full);
    else if (!keep.has(full) && fs.readFileSync(full, 'utf8').startsWith('// GENERATED by raptor-app/scripts/port_web_screens.mjs')) fs.rmSync(full);
  }
};
sweep(OUT);
for (const [web, text] of written) {
  const file = path.join(DESK, own(web));
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, text);
}
console.log(`wrote ${written.size} files into ${OUT}`);
